import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";import"./chunks/assets.JoaDwx61.js";var i=JSON.parse(`{"title":"Page Types in AL","description":"","frontmatter":{},"headers":[],"relativePath":"pages-and-user-interfaces/page-types.md","filePath":"pages-and-user-interfaces/page-types.md"}`),a={name:`pages-and-user-interfaces/page-types.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="page-types-in-al" tabindex="-1">Page Types in AL <a class="header-anchor" href="#page-types-in-al" aria-label="Permalink to “Page Types in AL”">​</a></h1><h2 id="what-are-page-types" tabindex="-1">What are Page Types? <a class="header-anchor" href="#what-are-page-types" aria-label="Permalink to “What are Page Types?”">​</a></h2><p>In Business Central, a Page Type determines the general purpose and behavior of a page object.</p><p>Remember, a page object defines the user interface through which users interact with Business Central data and functionality.</p><p>However, not all pages serve the same purpose.</p><p>For example:</p><ul><li>Some pages display lists of records, such as customers or products.</li><li>Others display detailed information about a single record.</li><li>Some pages allow users to enter information into a dialog.</li><li>Others provide a dashboard containing business information and activities.</li></ul><p>Business Central provides different page types to support these different use cases.</p><p>We specify the type of a page using the <code>PageType</code> property.</p><p>Example:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>page 50100 ProductList</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    PageType = List;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Here, <code>PageType = List</code> tells Business Central that this page is intended to display a list of records.</p><h2 id="common-page-types" tabindex="-1">Common Page Types <a class="header-anchor" href="#common-page-types" aria-label="Permalink to “Common Page Types”">​</a></h2><p>Let&#39;s explore the important page types you&#39;ll encounter when developing Business Central extensions.</p><h2 id="card" tabindex="-1">Card <a class="header-anchor" href="#card" aria-label="Permalink to “Card”">​</a></h2><p>A Card page is used to display and manage information about a single business entity or record.</p><p>A business entity is something the business needs to keep track of, such as a customer, vendor, item, or employee.</p><p>For example, a Customer Card displays information about one customer, including:</p><ul><li>Customer number.</li><li>Customer name.</li><li>Address and contact details.</li><li>Payment terms.</li><li>Credit limit.</li></ul><p>When to use it: When users need to view or manage the detailed information of one record at a time.</p><h3 id="example-card-page" tabindex="-1">Example Card Page <a class="header-anchor" href="#example-card-page" aria-label="Permalink to “Example Card Page”">​</a></h3><p>Filename: <code>CourseCard.Page.al</code></p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>namespace LearningAl;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>page 50103 &quot;Course Card&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    Caption = &#39;Course Card&#39;;</span></span>
<span class="line"><span>    PageType = Card;</span></span>
<span class="line"><span>    SourceTable = Course;</span></span>
<span class="line"><span>    ApplicationArea = All;</span></span>
<span class="line"><span>    UsageCategory = None;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    layout</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        area(Content)</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            group(General)</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                Caption = &#39;General&#39;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                field(&quot;Course Code&quot;; Rec.&quot;Course Code&quot;)</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    ToolTip = &#39;Specifies the unique code for the course.&#39;;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>                field(CourseName; Rec.CourseName)</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    ToolTip = &#39;Specifies the name of the course.&#39;;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>                field(CourseDescription; Rec.CourseDescription)</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    ToolTip = &#39;Specifies a description of the course.&#39;;</span></span>
<span class="line"><span>                    MultiLine = true;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>            group(Pricing)</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                Caption = &#39;Pricing &amp; Status&#39;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                field(Price; Rec.Price)</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    ToolTip = &#39;Specifies the price of the course.&#39;;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>                field(Status; Rec.Status)</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    ToolTip = &#39;Specifies the current status of the course.&#39;;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Here, <code>PageType = Card</code> tells Business Central that this page is intended for managing an individual product record.</p><p>Make sure in the <code>CourseList</code> Page (see below), you have <code>CoursePageId = &quot;Course Card&quot;</code>, this way, when you click on an ID, this course card page will open.</p><p><img src="/card-page.png" alt="card page" width="1323" height="636"></p><h2 id="list" tabindex="-1">List <a class="header-anchor" href="#list" aria-label="Permalink to “List”">​</a></h2><p>A List page displays a collection of records from a table.</p><p>For example, a Customer List displays multiple customers, usually in rows and columns.</p><p>Users can:</p><ul><li>Browse multiple records.</li><li>Search for records.</li><li>Apply filters.</li><li>Sort records.</li><li>Open individual records for more details.</li><li>Edit records directly where permitted.</li></ul><p>When to use it: When users need an overview of multiple records and a way to navigate between them.</p><h3 id="example-of-list-page" tabindex="-1">Example of List Page <a class="header-anchor" href="#example-of-list-page" aria-label="Permalink to “Example of List Page”">​</a></h3><p>File: <code>CourseList.Page.al</code>:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>namespace LearningAl;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>page 50102 CourseList</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    PageType = List;</span></span>
<span class="line"><span>    SourceTable = Course;</span></span>
<span class="line"><span>    Caption = &#39;Course List&#39;;</span></span>
<span class="line"><span>    ApplicationArea = All;</span></span>
<span class="line"><span>    UsageCategory = Lists;</span></span>
<span class="line"><span>    CardPageId = &quot;Course Card&quot;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    layout</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        area(Content)</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            repeater(General)</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                field(&quot;Course Code&quot;; Rec.&quot;Course Code&quot;)</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    ApplicationArea = All;</span></span>
<span class="line"><span>                    ToolTip = &#39;Specifies the unique code for the course.&#39;;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                field(CourseName; Rec.CourseName)</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    ApplicationArea = All;</span></span>
<span class="line"><span>                    ToolTip = &#39;Specifies the name of the course&#39;;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                field(CourseDescription; Rec.CourseDescription)</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    ApplicationArea = All;</span></span>
<span class="line"><span>                    ToolTip = &#39;Specifies the description of the course.&#39;;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>                field(Price; Rec.Price)</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    ApplicationArea = All;</span></span>
<span class="line"><span>                    ToolTip = &#39;Specifies a description of the course&#39;;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>                field(Status; Rec.Status)</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    ApplicationArea = All;</span></span>
<span class="line"><span>                    ToolTip = &#39;Specifies the current status of the course&#39;;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><img src="/list-page.png" alt="List Page" width="1618" height="701"></p><h2 id="document" tabindex="-1">Document <a class="header-anchor" href="#document" aria-label="Permalink to “Document”">​</a></h2><p>A Document page is used to manage business transactions or important business events.</p><p>Examples include:</p><ul><li>Sales Orders.</li><li>Purchase Orders.</li><li>Sales Invoices.</li><li>Purchase Invoices.</li><li>Sales Quotes.</li></ul><p>A document typically consists of two major sections:</p><ol><li>Header: Contains general information about the transaction, such as customer, document number, and posting date.</li><li>Lines: Contains the individual items or services involved in the transaction, including quantities and prices.</li></ol><p>When to use it: When users need to create, view, or manage business documents involving a header and associated lines.</p><h3 id="example-document-page" tabindex="-1">Example Document Page <a class="header-anchor" href="#example-document-page" aria-label="Permalink to “Example Document Page”">​</a></h3><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>page 50102 ProductDocument</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    PageType = Document;</span></span>
<span class="line"><span>    SourceTable = Product;</span></span>
<span class="line"><span>    Caption = &#39;Product Document&#39;;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Note: This is only a simplified illustration of the declaration. A real document page would normally have an appropriate document header table and an associated lines table.</p><h2 id="rolecenter" tabindex="-1">RoleCenter <a class="header-anchor" href="#rolecenter" aria-label="Permalink to “RoleCenter”">​</a></h2><p>A RoleCenter is the main dashboard or starting page presented to a user based on their assigned role.</p><p>It provides an overview of relevant business activities, performance indicators, and shortcuts to commonly used functionality.</p><p>For example, a Business Manager RoleCenter might display:</p><ul><li>Sales performance.</li><li>Outstanding invoices.</li><li>Pending approvals.</li><li>Cash flow information.</li><li>Frequently used business activities.</li></ul><p>When to use it: When designing a personalized workspace for a particular business role.</p><p>Example:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>page 50103 ProductManagerRoleCenter</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    PageType = RoleCenter;</span></span>
<span class="line"><span>    Caption = &#39;Product Manager&#39;;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Unlike most page types, a RoleCenter does not require a <code>SourceTable</code>. Its content is generally assembled from embedded parts.</p><h2 id="worksheet" tabindex="-1">Worksheet <a class="header-anchor" href="#worksheet" aria-label="Permalink to “Worksheet”">​</a></h2><p>A Worksheet page is designed for tasks that involve working with multiple entries in a tabular format, particularly data-entry and inquiry activities.</p><p>Examples include:</p><ul><li>Item Journals.</li><li>General Journals.</li><li>Payment Reconciliation Journals.</li><li>Planning Worksheets.</li></ul><p>Unlike a typical List page, a Worksheet is often designed around a particular task or process.</p><p>For example, an Item Journal allows users to enter multiple inventory adjustments before processing them.</p><p>When to use it: When users need to enter, review, or process multiple related entries as part of a business task.</p><p>Example:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>page 50104 ProductWorksheet</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    PageType = Worksheet;</span></span>
<span class="line"><span>    SourceTable = Product;</span></span>
<span class="line"><span>    Caption = &#39;Product Worksheet&#39;;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="cardpart" tabindex="-1">CardPart <a class="header-anchor" href="#cardpart" aria-label="Permalink to “CardPart”">​</a></h2><p><a href="https://images.openai.com/static-rsc-4/F_X3B-TKwl-GAk9Jb8NVjFxjIE1TH194HJIiRsQhZk_Ummb-mJyQ12jos0fmBGfh8ASwaz-H1CWTCXjVw-dOYMGHIO7nofQJ18HROFkouYW4fXhkBVneF1jrfjcrG1UehCzQQJTnlRUXyNU5JZvbHafdxIkfdJKmEI5ET2FYC4c?purpose=inline" target="_blank" rel="noreferrer">Pages - The Interactive Interface | Programming Microsoft Dynamics 365 Business Central</a></p><p><a href="https://subscription.packtpub.com/book/business-and-other/9781789137798/4/ch04lvl1sec34/card-page?utm_source=chatgpt.com" target="_blank" rel="noreferrer">subscription.packtpub.com</a></p><p>A CardPart is a smaller page designed to be embedded inside another page.</p><p>It displays information about a single entity, usually as part of a FactBox or another page composition.</p><p>For example, while viewing a Customer Card, a FactBox might display additional information about the selected customer, such as:</p><ul><li>Customer statistics.</li><li>Outstanding balances.</li><li>Sales history.</li></ul><p>When to use it: When you want to display additional information about a single record without requiring users to navigate away from the current page.</p><p>Example:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>page 50105 ProductDetailsPart</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    PageType = CardPart;</span></span>
<span class="line"><span>    SourceTable = Product;</span></span>
<span class="line"><span>    Caption = &#39;Product Details&#39;;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="_2-7-listpart" tabindex="-1">2.7 ListPart <a class="header-anchor" href="#_2-7-listpart" aria-label="Permalink to “2.7 ListPart”">​</a></h2><p><a href="https://images.openai.com/static-rsc-4/Pga1BHB3yk5fDo5v5fkzX4qn8btEaE90NkTjEX_yKJy_9o-y02CnrftQbwxLoFSjqBSrr4_9j3ReyjxiT3H4J8MPaRIeCEf5xusgF_zbPB-FqNgQnx-yEv-OBjuMmkkE_hiWzdM1AyVIOCM23ofBi6f5d-YJpz5L9xDQBKxUDXY?purpose=inline" target="_blank" rel="noreferrer">Adding a FactBox to a page - Business Central | Microsoft Learn</a></p><p><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-adding-a-factbox-to-page?utm_source=chatgpt.com" target="_blank" rel="noreferrer">learn.microsoft.com</a></p><p>A ListPart is a smaller page designed to display a collection of records inside another page.</p><p>For example, a Sales Order Document page can contain a ListPart displaying the individual sales order lines.</p><p>A ListPart can also be embedded in a FactBox to display related records.</p><p>When to use it: When you need to display multiple related records within another page.</p><p>Example:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>page 50106 ProductHistoryPart</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    PageType = ListPart;</span></span>
<span class="line"><span>    SourceTable = Product;</span></span>
<span class="line"><span>    Caption = &#39;Product History&#39;;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Important distinction:</p><ul><li><code>CardPart</code> displays information about a single record.</li><li><code>ListPart</code> displays a collection of records.</li></ul><p>Both are designed to be embedded inside other pages rather than used as standalone pages.</p><h2 id="_2-8-listplus" tabindex="-1">2.8 ListPlus <a class="header-anchor" href="#_2-8-listplus" aria-label="Permalink to “2.8 ListPlus”">​</a></h2><p><a href="https://images.openai.com/static-rsc-4/1SaH0O5h7_0MQbOpx8HacILMz7gqMls1HL23Twr_gzet3Qnuec2taBaP7Xae-rLVSwMabRsYQcGb0Wo8im2agcOtS7Plr-rULu4j5AW7fpMMGOAWr6X8M-HIObcZoIq6gU2ZPRPvmG1Xw_QPO3YLFmG4YDj2KW7n6Jd21Hj7Cm0?purpose=inline" target="_blank" rel="noreferrer">Designing List Pages for Business Central - Business Central | Microsoft Learn</a></p><p><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-designing-list-pages?utm_source=chatgpt.com" target="_blank" rel="noreferrer">learn.microsoft.com</a></p><p>A ListPlus page combines information about a single entity with a prominent embedded list.</p><p>For example, you might have a page displaying information about a particular customer alongside a list of related transactions.</p><p>When to use it: When users need to view details about one entity alongside a collection of related records, with the list being a prominent part of the page.</p><p>Example:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>page 50107 ProductOverview</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    PageType = ListPlus;</span></span>
<span class="line"><span>    SourceTable = Product;</span></span>
<span class="line"><span>    Caption = &#39;Product Overview&#39;;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Unlike a Card page, a ListPlus page must contain at least one <code>ListPart</code>.</p><h2 id="_2-9-standarddialog" tabindex="-1">2.9 StandardDialog <a class="header-anchor" href="#_2-9-standarddialog" aria-label="Permalink to “2.9 StandardDialog”">​</a></h2><p><a href="https://images.openai.com/static-rsc-4/_bAb2vKwT3abrTlzhaXRtrDmdjknokLZwRPXBO8S8RN0Z23uRLUgNkwMwv5CJLrTYsgeeAqLe9FTXmk3cEfCAR0q6haidB-x9llqP3zlQ_-mkhd5PashD3k1OGzcsM6OVhcp3xmYNmOcuTUz4LjcsFgnyF2rcw_gIDXO_nEgHQo?purpose=inline" target="_blank" rel="noreferrer">Linked Customer and Vendor</a></p><p><a href="https://learn.d365.global/Tutorials/D365Guides/D365BusinessCentral/BusinessCentralTips/CustomerVendor/LinkedCustomerVendor?utm_source=chatgpt.com" target="_blank" rel="noreferrer">learn.d365.global</a></p><p>A StandardDialog page is used to present users with a dialog containing fields or other inputs needed to perform a task.</p><p>For example, you could ask a user to:</p><ul><li>Select a date.</li><li>Enter a quantity.</li><li>Choose a product category.</li><li>Provide parameters for an operation.</li></ul><p>When to use it: When users need to provide input or information before proceeding with a particular operation.</p><p>Example:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>page 50108 ProductDialog</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    PageType = StandardDialog;</span></span>
<span class="line"><span>    Caption = &#39;Product Selection&#39;;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="_2-10-confirmationdialog" tabindex="-1">2.10 ConfirmationDialog <a class="header-anchor" href="#_2-10-confirmationdialog" aria-label="Permalink to “2.10 ConfirmationDialog”">​</a></h2><p><a href="https://images.openai.com/static-rsc-4/63uoOyLNLPzdan1InYT13GW18Uom_0zL0amq-wn4pySpoi6MWbf-O54tHp5lXm3ngzfS06uDRkEACvwQ-2AoH7I_E1K5ZERc_NDh6s-QOGvbyFmafcXF1TmRY417vfbdnHVAOIas3FLYEsTMo49UCzBHq04fHck3sY5dPkXkqoU?purpose=inline" target="_blank" rel="noreferrer">Siehe verbesserte Nutzungsfreundlichkeit für Lager und Bestand | Microsoft Learn</a></p><p><a href="https://learn.microsoft.com/de-de/dynamics365/release-plan/2023wave2/smb/dynamics365-business-central/usability-improves-warehouse-inventory?utm_source=chatgpt.com" target="_blank" rel="noreferrer">learn.microsoft.com</a></p><p>A ConfirmationDialog page is used to ask users to confirm an action or acknowledge an exceptional situation.</p><p>For example:</p><ul><li>Are you sure you want to delete this product?</li><li>Do you want to continue with this operation?</li><li>Are you sure you want to post this document?</li></ul><p>When to use it: When an operation requires explicit confirmation from the user.</p><p>Example:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>page 50109 DeleteConfirmation</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    PageType = ConfirmationDialog;</span></span>
<span class="line"><span>    Caption = &#39;Confirm Deletion&#39;;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="_2-11-navigatepage" tabindex="-1">2.11 NavigatePage <a class="header-anchor" href="#_2-11-navigatepage" aria-label="Permalink to “2.11 NavigatePage”">​</a></h2><p><a href="https://images.openai.com/static-rsc-4/PC591xgP4twjfw5YCcRQhgf8hT_KdPlmUbJ3U-YEPIXDtZenT_BPmviIlUGOa-E1xNFJPbVkVtMMqdYhQNjllxzqjS1TdgufcWFcnXoxzScfw_L68v3PZJ7A8M8JhlHOCuxSNp8qREtxrFmc8C4cHYyXrgie9stdcEbj2NSqvI8?purpose=inline" target="_blank" rel="noreferrer">Designing Assisted Setup Guides - Business Central | Microsoft Learn</a></p><p><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-designing-navigate-pages?utm_source=chatgpt.com" target="_blank" rel="noreferrer">learn.microsoft.com</a></p><p>A NavigatePage is used to create a wizard-like experience that guides users through a sequence of steps to complete a task.</p><p>For example, imagine setting up a new product:</p><ol><li>Enter basic product information.</li><li>Select a product category.</li><li>Configure pricing.</li><li>Review the information.</li><li>Complete the setup.</li></ol><p>Instead of presenting everything on one page, a NavigatePage can guide the user through these steps.</p><p>When to use it: When a task involves multiple sequential steps and users need guidance through the process.</p><p>Example:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>page 50110 ProductSetupWizard</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    PageType = NavigatePage;</span></span>
<span class="line"><span>    Caption = &#39;Product Setup Wizard&#39;;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="_2-12-headlinepart" tabindex="-1">2.12 HeadlinePart <a class="header-anchor" href="#_2-12-headlinepart" aria-label="Permalink to “2.12 HeadlinePart”">​</a></h2><p><a href="https://images.openai.com/static-rsc-4/9CDZLAwkVKU6r3V4chHfcjoUi6zvGSoDpjcdJZYCK2dOqLXoZUfvQeyLSd8SRu5iixlmaUL-3FlbnRs_Iuei_tgiI5530gpJs8bFHrERk5ROELIXLRE2Fb2XYa7tegMpv3mnrBbm3uBfAsJYR3kUki7Ay8tDJB1ajSDaDhdi2VE?purpose=inline" target="_blank" rel="noreferrer">Simple Role Center example - Business Central | Microsoft Learn</a></p><p><a href="https://learn.microsoft.com/es-mx/dynamics365/business-central/dev-itpro/developer/devenv-simple-role-center-example?utm_source=chatgpt.com" target="_blank" rel="noreferrer">learn.microsoft.com</a></p><p>A HeadlinePart is a page designed to display contextual headlines and insights within a RoleCenter.</p><p>For example, a Business Manager RoleCenter might display headlines about:</p><ul><li>Business performance.</li><li>Sales activities.</li><li>Outstanding tasks.</li><li>Relevant business insights.</li></ul><p>When to use it: When you want to display changing or contextual headlines on a RoleCenter.</p><p>Example:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>page 50111 ProductHeadline</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    PageType = HeadlinePart;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="_2-13-api" tabindex="-1">2.13 API <a class="header-anchor" href="#_2-13-api" aria-label="Permalink to “2.13 API”">​</a></h2><p>An API page is a special page type used to expose Business Central data and functionality to external applications through web services.</p><p>Unlike the page types we&#39;ve discussed so far, API pages are not designed for users to interact with through the Business Central user interface.</p><p>For example, suppose you have a React application that needs to retrieve customer records from Business Central.</p><p>You can create an API page that exposes customer data, allowing your React application to communicate with Business Central through HTTP requests.</p><p>When to use it: When integrating Business Central with external applications and services.</p><p>Example:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>page 50112 ProductsAPI</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    PageType = API;</span></span>
<span class="line"><span>    APIPublisher = &#39;learning&#39;;</span></span>
<span class="line"><span>    APIGroup = &#39;inventory&#39;;</span></span>
<span class="line"><span>    APIVersion = &#39;v1.0&#39;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    EntityName = &#39;product&#39;;</span></span>
<span class="line"><span>    EntitySetName = &#39;products&#39;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    SourceTable = Product;</span></span>
<span class="line"><span>    ODataKeyFields = SystemId;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>We&#39;ll cover API pages and integrations separately when we get to Business Central integrations.</p><p>Important: API pages generate web service endpoints and cannot be displayed as ordinary user interface pages.</p><h2 id="_2-14-promptdialog" tabindex="-1">2.14 PromptDialog <a class="header-anchor" href="#_2-14-promptdialog" aria-label="Permalink to “2.14 PromptDialog”">​</a></h2><p>A PromptDialog is a specialized page type for creating generative AI experiences with the Copilot look and feel.</p><p>It allows developers to build interactions where users provide prompts and receive AI-generated responses.</p><p>When to use it: When developing Copilot-style experiences within Business Central.</p><p>This is an advanced page type introduced in runtime 12.1. It also requires the <code>PromptMode</code> property.</p><p>You don&#39;t need to master this one yet.</p><h2 id="_3-other-specialized-page-types" tabindex="-1">3. Other Specialized Page Types <a class="header-anchor" href="#_3-other-specialized-page-types" aria-label="Permalink to “3. Other Specialized Page Types”">​</a></h2><p>There are additional page types worth recognizing, even though you won&#39;t encounter them as frequently when building ordinary business application interfaces.</p><table tabindex="0"><thead><tr><th>Page type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>ReportPreview</code></td><td>Used for previewing reports.</td></tr><tr><td><code>ReportProcessingOnly</code></td><td>Used for report processing without presenting a normal report output.</td></tr><tr><td><code>XmlPort</code></td><td>Used for XMLPort-related page functionality.</td></tr><tr><td><code>UserControlHost</code></td><td>Hosts a single user control in the Business Central client.</td></tr><tr><td><code>ConfigurationDialog</code></td><td>Intended for collecting configuration input for a process or automation.</td></tr></tbody></table><p><code>ConfigurationDialog</code> is currently under development and cannot be used in an extension, according to Microsoft&#39;s documentation.</p><p>You don&#39;t need to implement these for now. Just recognize their purpose.</p><p>Source: <a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/properties/devenv-pagetype-property?wt.mc_id=DX-MVP-5004336&amp;utm_source=chatgpt.com" target="_blank" rel="noreferrer">Microsoft – PageType Property</a>.</p><h2 id="_4-understanding-page-types-by-their-purpose" tabindex="-1">4. Understanding Page Types by Their Purpose <a class="header-anchor" href="#_4-understanding-page-types-by-their-purpose" aria-label="Permalink to “4. Understanding Page Types by Their Purpose”">​</a></h2><p>Rather than memorizing all these page types individually, let&#39;s organize them according to the problems they solve.</p><table tabindex="0"><thead><tr><th>Category</th><th>Page types</th><th>Main purpose</th></tr></thead><tbody><tr><td>Entity-oriented</td><td>Card, Document, ListPlus</td><td>Work with an individual business entity or transaction.</td></tr><tr><td>Collection-oriented</td><td>List, Worksheet</td><td>Work with multiple records or entries.</td></tr><tr><td>Embedded pages</td><td>CardPart, ListPart, HeadlinePart</td><td>Display information inside other pages.</td></tr><tr><td>Dashboard</td><td>RoleCenter</td><td>Provide a workspace for a particular business role.</td></tr><tr><td>Dialogs</td><td>StandardDialog, ConfirmationDialog, NavigatePage, PromptDialog</td><td>Collect input, confirm actions, or guide users through tasks.</td></tr><tr><td>Integration</td><td>API</td><td>Expose data and functionality to external applications.</td></tr></tbody></table><p>One particularly important distinction is between entity-oriented and collection-oriented pages.</p><ul><li>Entity-oriented pages focus on one business entity, such as a customer, product, or sales order.</li><li>Collection-oriented pages focus on multiple records, such as a list of customers or journal entries.</li></ul><p>This distinction helps you choose the appropriate page type when designing an extension. </p><p><a href="https://www.google.com/s2/favicons?domain=https://learn.microsoft.com&amp;sz=32" target="_blank" rel="noreferrer">image</a></p><p>Microsoft Learn+1</p><h2 id="_5-quick-comparison-card-vs-list-vs-document-vs-worksheet" tabindex="-1">5. Quick Comparison: Card vs List vs Document vs Worksheet <a class="header-anchor" href="#_5-quick-comparison-card-vs-list-vs-document-vs-worksheet" aria-label="Permalink to “5. Quick Comparison: Card vs List vs Document vs Worksheet”">​</a></h2><p>These four are particularly important when developing ordinary Business Central applications.</p><p><a href="https://images.openai.com/static-rsc-4/M6DLAiL5pLzrh_hO_Po93dGUYVAUumt5FL71k2nfjHUCEYsAIOIhLUdgfebWF4Yb8X8JaNdT1B8IrxukvEz9ShABGBkOaYKOg7twb2kKRK-jVE2r5dlX5-NNdqsbwF_FOrbWvD79GlSNwtVFpBZ1pzPFb6tOZgDptSsEkoTHExQ?purpose=inline" target="_blank" rel="noreferrer">Dynamics 365 Business Central vs Customer Engagement</a></p><p>Card</p><p>Manages one record.</p><p>Example: Customer Card.</p><p><a href="https://images.openai.com/static-rsc-4/zaoaJjhlAwKwd_ze2KPRNNDpn8AhtpLyIEvGwOK_RvhhMNrNgyXj4itHCxQcqKc7RKQKoNCS86BzG7HFUdEAaC9Jlguryi_40exiDZsKcy6vZhm5Q_q3XjmAuxlElTmP0l5n3WRmg0VLB0nxrW9o9a3yojdH0-Ym34qtJnoTrj4?purpose=inline" target="_blank" rel="noreferrer">cmty_blog_detail</a></p><p>List</p><p>Displays multiple records.</p><p>Example: Customer List.</p><p><a href="https://images.openai.com/static-rsc-4/E5N7DHWtRYwSwXeJaS7l8k5BfdVzvZ7uU8u6h89T503zp1vi8aaShbTKscpt6nZS7FrOVK0DkLO0FAdheHXur4nsVG_vwtvZ6S2cd6kOC2WmsTEq4Qf5QbQ2kORh5EuCnWvl9yQ09cLoNDKzR4ArQO_f9OehhasLVR39MURtMhc?purpose=inline" target="_blank" rel="noreferrer">How to Manage the Sales Process in Microsoft Dynamics 365 Business Central</a></p><p>Document</p><p>Manages a business transaction, typically with a header and lines.</p><p>Example: Sales Order.</p><p><a href="https://images.openai.com/static-rsc-4/wtBplJ1YtvHbpnBjgA-deiLyZbtz6W-q4txaACo7bUq27U4-TAlo51smxJGtOh3sdI7ibPEAUQG60ixZ0AMMfn8HNNR-ZgqEdsGRFd9rNxkUVzWpd1v9AfeBXAyX8fspchW2dXe0M4wwd_z6pVOQqQ4szXkG8LOVxU0Xy2kskFU?purpose=inline" target="_blank" rel="noreferrer">Standard General Journal Business Central at David Sells blog</a></p><p>Worksheet</p><p>Supports task-oriented, line-based data entry.</p><p>Example: General Journal.</p><h2 id="_6-important-things-to-remember" tabindex="-1">6. Important Things to Remember <a class="header-anchor" href="#_6-important-things-to-remember" aria-label="Permalink to “6. Important Things to Remember”">​</a></h2><ol><li>The <code>PageType</code> property determines the general purpose and layout behavior of a page.</li><li>A Card page manages an individual record, while a List page displays multiple records.</li><li>Document pages represent business transactions and commonly contain headers and lines.</li><li>RoleCenter pages provide a starting workspace for users.</li><li>CardPart and ListPart pages are designed to be embedded inside other pages.</li><li>API pages expose Business Central data to external applications rather than displaying a user interface.</li><li>Not every page type is associated with a <code>SourceTable</code>.</li></ol><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to “Further Reading”">​</a></h2><ul><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-page-types-and-layouts" target="_blank" rel="noreferrer">Microsoft Learn – Page Types and Layouts</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/properties/devenv-pagetype-property" target="_blank" rel="noreferrer">Microsoft Learn – PageType Property</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-api-pagetype" target="_blank" rel="noreferrer">Microsoft Learn – API Pages</a></li></ul>`,184)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};